+  assert_entity_expanded_size_equals(parser, "", 0);
+  assert_entity_expanded_size_equals(parser, "123", 3);
+  assert_entity_expanded_size_equals(parser, "&amp;&apos;&gt;&lt;&quot;",
+                                     strlen("&amp;&apos;&gt;&lt;&quot;") + 5);
